        $btn_close->setLabel("Fechar"); $btn_close->setImage('fas:times');
        $embed = new self($param);
        $embed->form->addHeaderWidget($btn_close);
        $embed->onEdit($param);
        $page->add($embed->form);
        $page->show();
    }
}

